}

Method.Source:
/// <summary>
/// Constructs the controller class object
/// </summary>
public static METInventTransferParmReceiveController construct(SysOperationExecutionMode _executionMode = SysOperationExecutionMode::Synchronous)
{
    METInventTransferParmReceiveController controller = new METInventTransferParmReceiveController();
    controller.parmExecutionMode(_executionMode);
    return controller;
}

/// <summary>
/// Runs the controller class
/// </summary>
public static void main(Args _args)
{
    METInventTransferParmReceiveController controller = METInventTransferParmReceiveController::construct();
    
    controller.parmArgs(_args);
    controller.startOperation();
}

/// <summary>
/// Sets caption of a batch job
/// </summary>
public ClassDescription defaultCaption()
{
    return "@MET:METInventTransferParmReceiveService";
}
